import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In triangle ABC with side lengths AB={a}, BC={b}, and CA={c}, there is a unique interior point P such that the three directed angles ∠PAB, ∠PBC, and ∠PCA are equal. Let t = tan(∠PAB). Let d_a, d_b, and d_c denote the perpendicular distances from P to the lines BC, CA, and AB, respectively. Write t in lowest terms as m/n and write S = d_a/d_b + d_b/d_c + d_c/d_a in lowest terms as u/v. Find the value of m + n + u + v.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
import math
# Generate a scaled primitive Pythagorean triple to guarantee integer area.
# This yields many nontrivial scalene Heron triangles while keeping arithmetic manageable.
for _ in range(1000):
    m = rng.randint(5, 20)
    n = rng.randint(1, m-1)
    if math.gcd(m, n) != 1:
        continue
    # Opposite parity condition for primitive triple
    if ((m - n) % 2) == 0:
        continue
    k = rng.randint(1, 3)
    leg1 = k * (m*m - n*n)
    leg2 = k * (2*m*n)
    hyp = k * (m*m + n*n)
    # Sort so that a <= b <= c (c will be the hypotenuse)
    a, b = sorted([leg1, leg2])
    c = hyp
    if a <= 0 or b <= 0 or c <= 0:
        continue
    if a + b <= c:
        continue
    # Compute t = 4*Area / (a^2 + b^2 + c^2); for right triangles area = a*b/2
    t_num = 2 * a * b
    t_den = a*a + b*b + c*c
    g = math.gcd(t_num, t_den)
    t_num //= g
    t_den //= g
    # Avoid trivial denominators to keep difficulty nontrivial
    if t_den <= 1:
        continue
    # Compute S = (a^3 + b^3 + c^3) / (a*b*c)
    s_num = a**3 + b**3 + c**3
    s_den = a * b * c
    g2 = math.gcd(s_num, s_den)
    s_num //= g2
    s_den //= g2
    if s_den <= 1:
        continue
    total = t_num + t_den + s_num + s_den
    if total > 10**7:
        # keep answers within reasonable bounds
        continue
    return {'a': a, 'b': b, 'c': c}
# Fallback to a classic Heron triangle if random generation fails
return {'a': 13, 'b': 14, 'c': 15}

    def verifier(assign):
import math
from math import gcd
# Extract and validate inputs
try:
    a = int(assign.get('a', 0))
    b = int(assign.get('b', 0))
    c = int(assign.get('c', 0))
except Exception:
    return (False, None)
if min(a, b, c) <= 0:
    # invalid sides
    return (False, None)
# Triangle inequality
if a + b <= c or a + c <= b or b + c <= a:
    return (False, None)
# Order sides
a, b, c = sorted([a, b, c])
# Compute area K
if a*a + b*b == c*c:
    # Right triangle (common case from generator)
    K = a*b/2
else:
    # Use Heron's formula; require integer area for rational t
    s = (a + b + c) / 2.0
    p = s * (s - a) * (s - b) * (s - c)
    if p <= 0:
        return (False, None)
    Kf = math.sqrt(p)
    # Accept only near-integer areas to ensure rational t
    if abs(Kf - round(Kf)) < 1e-9:
        K = int(round(Kf))
    else:
        # Area not integral; in this family we expect rational t, so reject
        return (False, None)
# Compute t = 4K / (a^2 + b^2 + c^2) reduced
t_num = int(round(4 * K))
t_den = a*a + b*b + c*c
g = gcd(t_num, t_den)
t_num //= g
t_den //= g
if t_den <= 1:
    # too trivial; enforce difficulty
    return (False, None)
# Compute S = (a^3 + b^3 + c^3) / (a*b*c) reduced
s_num = a**3 + b**3 + c**3
s_den = a * b * c
g2 = gcd(s_num, s_den)
s_num //= g2
s_den //= g2
if s_den <= 1:
    return (False, None)
answer = t_num + t_den + s_num + s_den
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

